            with open(full, "wb") as f:
                f.write(op.get("c", "").encode("utf-8"))
            if "m" in op:
                os.utime(full, (op["m"], op["m"]))
        elif kind == "touch":
            os.utime(full, (op["m"], op["m"]))
        elif kind == "sleep":
            time.sleep(op["s"])
        elif kind == "touchall":
            if os.path.isdir(full):
                for d, dns, fns in os.walk(full, topdown=False):
